MATCH (h:PlantItem {tag: 'H-3801'}), (v:Valve)-[:line_to]-(h), (loop:ProcessControlFunction)-[:send_signal_to*1..]->(actuator:PlantItem)-[:control]->(v)
RETURN DISTINCT loop.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'D-3001'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (f:PlantItem {tag: 'F-3901'})-[:line_to]-(v:Valve)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to*]-(c:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'TI-44040'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LSHH-29009'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'V-1401'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem {loop_tag: 'LIC-6019'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(f:PlantItem {tag: 'F-201B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'V-1402'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id, tag;

MATCH (v:PlantItem:AngleBallValve {unit_id: '32'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (c:ProcessControlFunction {loop_tag: 'LIC-31001'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'PIC-18027'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'E-1201'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (m:PlantItem:StaticMixer {unit_id: '16'})
RETURN m.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'E-1001'})-[:line_to]-(v:Valve)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'V-5801'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:Valve)-[:line_to*1..]->(a:PlantItem {tag: 'EA-1001'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (s:PlantItem {no_inflow: true})-[:line_to*1..]->(:PlantItem {tag: 'E-3502'})
RETURN DISTINCT s.tag AS tag
ORDER BY tag;
